constexpr int fib(int n) {
    return (n <= 1) ? n : fib(n - 1) + fib(n - 2);
}

// Compile-Time: Function call replaced by value (6765).
// Zero runtime overhead.
constexpr int fast_result = fib(20);


int runtime_input(); // Value unknown until execution

// Runtime Fallback: Evaluated at runtime like a standard function.
// Standard function call overhead generated.
int slow_result = fib(runtime_input());


// Memory/Initialization Impact (Guarantees Static Storage)
class Settings { int id; };

constexpr Settings make_settings() { return Settings{42}; }

// Forces static initialization (zero/constant init).
// Guarantees zero memory initialization overhead at runtime.
constinit const Settings default_set = make_settings();
